    Asset = apps.get_model('devices', 'Asset')
    IssuedAssetTag = apps.get_model('devices', 'IssuedAssetTag')
    Sequence = apps.get_model('devices', 'AssetIdSequence')
    Activity = apps.get_model('common', 'SystemActivityLog')

    for device in DeviceType.objects.using(database).iterator(chunk_size=1000):
        device.tag_category_code = suggest_tag_category(device.name)
        device.save(using=database, update_fields=['tag_category_code'])

    current_tags = Asset.objects.using(database).values_list('asset_tag', flat=True)
    for tag in current_tags.iterator(chunk_size=1000):
        if tag.strip():
            IssuedAssetTag.objects.using(database).get_or_create(tag=tag.strip().upper())

    actions = Activity.objects.using(database).filter(action='DELETE_ASSET', module='Assets')
    for description in actions.values_list('description', flat=True).iterator(chunk_size=1000):
        match = re.match(r'^Deleted asset \[([^\n]+?)\] from ', description)
        if match:
            tag = match[1].strip().upper()
            if tag and len(tag) <= 150:
                IssuedAssetTag.objects.using(database).get_or_create(tag=tag)

    Sequence.objects.using(database).get_or_create(pk=1)


